```java
import java.io.FileOutputStream;
import java.io.OutputStreamWriter;
import java.io.PrintStream;

public class DirectToFileWriter {
    public static void main(String[] args) {
        String filename = "output.txt";
        FileOutputStream fos = null;
        PrintStream ps = null;
        try {
            fos = new FileOutputStream(filename);
            OutputStreamWriter osw = new OutputStreamWriter(fos, "UTF-8");
            ps = new PrintStream(osw, true); // auto-flush after each write
            ps.println("First line of data");
            ps.println("Second line of data");
        } catch (Exception e) {
            e.printStackTrace();
        } finally {
            if (ps != null) {
                ps.close();
            }
            if (fos != null) {
                try {
                    fos.close();
                } catch (Exception e) {
                    e.printStackTrace();
                }
            }
        }
    }
}
```

In this code, `PrintStream` is set to auto-flush with `PrintStream(osw, true)`, meaning it will automatically write to the file after each operation and close the streams properly in the `finally` block to prevent resource leaks.

